/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

M2C_UNK workerLockAcquire();                            /* extern */
M2C_UNK workerLockRelease();                            /* extern */
M2C_UNK setSoundChannelRamp(s32, s32, s32, M2C_UNK, s32); /* extern */
extern u8 gWorkerThreadActive;

/* Ramps one sound channel under the worker lock, if the sound worker thread is running. */ void rampSoundChannelLocked(s32 channel, s32 duration, s32 target) {
    if (gWorkerThreadActive != 0) {
        workerLockAcquire();
        setSoundChannelRamp(channel & 0xFF, duration & 0xFFFF, target & 0xFF, 0, 0);
        workerLockRelease();
    }
}
